--
-- Table structure for table `deals`
--

DROP TABLE IF EXISTS `deals`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `deals` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `deal_number` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `offer_id` bigint unsigned NOT NULL,
  `reservation_id` bigint unsigned DEFAULT NULL,
  `purchase_request_id` bigint unsigned DEFAULT NULL,
  `buyer_organization_id` bigint unsigned NOT NULL,
  `seller_organization_id` bigint unsigned NOT NULL,
  `buyer_user_id` bigint unsigned NOT NULL,
  `seller_user_id` bigint unsigned DEFAULT NULL,
  `warehouse_id` bigint unsigned DEFAULT NULL,
  `quantity` decimal(14,2) NOT NULL,
  `unit_price` decimal(18,4) NOT NULL,
  `currency_code` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'YER',
  `base_currency` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'YER',
  `exchange_rate_snapshot` decimal(18,6) NOT NULL DEFAULT '1.000000',
  `rate_source` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL_ADMIN_RATE',
  `rate_timestamp` timestamp NULL DEFAULT NULL,
  `base_amount` decimal(18,4) NOT NULL,
  `discount_amount` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `tax_rate_snapshot` decimal(6,4) NOT NULL DEFAULT '0.0000',
  `tax_amount` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `platform_fee_rate_snapshot` decimal(6,4) NOT NULL DEFAULT '0.0000',
  `platform_fee_amount` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `delivery_fee_amount` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `buyer_total_amount` decimal(18,4) NOT NULL,
  `seller_net_amount` decimal(18,4) NOT NULL,
  `status` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING_SELLER_APPROVAL',
  `delivery_method` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PICKUP',
  `delivery_address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `inspection_window_hours` int unsigned NOT NULL DEFAULT '48',
  `inspection_deadline_at` timestamp NULL DEFAULT NULL,
  `accepted_at` timestamp NULL DEFAULT NULL,
  `dispatched_at` timestamp NULL DEFAULT NULL,
  `delivered_at` timestamp NULL DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
