CREATE TABLE `demand_matches` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `demand_id` bigint unsigned NOT NULL,
  `offer_id` bigint unsigned NOT NULL,
  `buyer_organization_id` bigint unsigned NOT NULL,
  `seller_organization_id` bigint unsigned NOT NULL,
  `requested_quantity` decimal(14,2) NOT NULL,
  `match_score` decimal(5,2) NOT NULL DEFAULT '0.00',
  `match_reasons` json DEFAULT NULL,
  `estimated_total` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `expires_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `demand_matches_demand_id_offer_id_unique` (`demand_id`,`offer_id`),
  KEY `demand_matches_offer_id_foreign` (`offer_id`),
  KEY `demand_matches_buyer_organization_id_status_index` (`buyer_organization_id`,`status`),
  KEY `demand_matches_seller_organization_id_status_index` (`seller_organization_id`,`status`),
  CONSTRAINT `demand_matches_buyer_organization_id_foreign` FOREIGN KEY (`buyer_organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `demand_matches_demand_id_foreign` FOREIGN KEY (`demand_id`) REFERENCES `demands` (`id`) ON DELETE CASCADE,
  CONSTRAINT `demand_matches_offer_id_foreign` FOREIGN KEY (`offer_id`) REFERENCES `offers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `demand_matches_seller_organization_id_foreign` FOREIGN KEY (`seller_organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `demand_matches_quantity_positive` CHECK ((`requested_quantity` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
