(13,'reservation.timeout','30','integer','operations','مهلة حجز المخزون بالدقائق','Inventory hold in minutes','30',1,1,NULL,NULL,'2026-09-25 21:15:54','2026-09-25 21:16:28'),(14,'inspection.window','48','integer','operations','نافذة الفحص بعد التسليم بالساعات','Post-delivery inspection window in hours','48',1,1,NULL,NULL,'2026-09-25 21:15:54','2026-09-25 21:15:54'),(15,'demand.expiry_days','14','integer','operations','انتهاء طلب الشراء بالأيام','Demand lifetime in days','14',1,0,NULL,NULL,'2026-09-25 21:15:54','2026-09-25 21:15:54'),(16,'offer.expiry_days','60','integer','operations','انتهاء العرض بالأيام','Offer lifetime in days','60',1,0,NULL,NULL,'2026-09-25 21:15:54','2026-09-25 21:15:54'),(17,'offer.requires_review','0','boolean','operations','مراجعة المشرف قبل نشر العرض','Moderate offers before publishing','0',1,0,NULL,NULL,'2026-09-25 21:15:54','2026-09-25 21:15:54'),(18,'marketplace.featured_limit','8','integer','operations','عدد العروض المميزة المعروضة أعلى السوق','Featured offers shown at the top of the marketplace','8',1,1,NULL,NULL,'2026-09-25 21:15:54','2026-09-25 21:15:54'),(19,'auth.google_auto_register','1','boolean','auth','إنشاء حساب تلقائياً عند أول دخول عبر جوجل','Create an account on first Google sign-in when none matches','1',1,0,NULL,NULL,'2026-09-25 21:15:54','2026-09-25 21:15:54'),(20,'auth.google_enabled','0','boolean','auth','السماح بفتح الجلسة عبر حساب جوجل','Allow sessions to be opened with a Google account','0',1,1,NULL,NULL,'2026-09-25 21:15:54','2026-09-25 21:15:54'),(21,'auth.google_client_id','','string','auth','معرّف العميل من مشروع جوجل لهذا النشر','OAuth client ID issued to this deployment by Google Cloud','',1,1,NULL,NULL,'2026-09-25 21:15:54','2026-09-25 21:15:54'),(22,'account.require_phone_number','1','boolean','auth','إلزام إكمال رقم الهاتف قبل التصرف التجاري','A phone number must be completed before an account can trade','1',1,1,NULL,NULL,'2026-09-25 21:15:54','2026-09-25 21:15:54'),(23,'account.require_national_id','0','boolean','auth','إلزام إكمال الرقم الوطني أو المدني','A national or civil ID must be completed before an account can trade','0',1,1,NULL,NULL,'2026-09-25 21:15:54','2026-09-25 21:15:54'),(24,'account.max_organizations_per_account','3','integer','auth','أقصى ما يُنشئه حساب واحد من منشآت؛ صفر يعني بلا سقف','Maximum number of businesses one account may found; 0 means unlimited','3',1,0,NULL,NULL,'2026-09-25 21:15:54','2026-09-25 21:15:54'),(25,'legal.require_commercial_registration','0','boolean','legal','هل رقم السجل التجاري إلزامي عند تسجيل منشأة','Require a commercial registration number when a business registers','0',1,0,NULL,NULL,'2026-09-25 21:15:54','2026-09-25 21:15:54'),(26,'legal.require_vat_number','0','boolean','legal','هل الرقم الضريبي إلزامي عند تسجيل منشأة','Require a tax number when a business registers','0',1,0,NULL,NULL,'2026-09-25 21:15:54','2026-09-25 21:15:54'),(27,'marketplace.require_verified_to_trade','1','boolean','trust','منع النشر وطلبات الشراء والصفقات قبل مراجعة وثائق المنشأة','Refuse commercial actions until the business record has been reviewed','1',1,1,NULL,NULL,'2026-09-25 21:15:54','2026-09-25 21:15:54'),(28,'community.moderate_before_publishing','0','boolean','trust','مراجعة التعليق قبل إظهاره للعامة','Hold public comments until a reviewer publishes them','0',1,1,NULL,NULL,'2026-09-25 21:15:54','2026-09-25 21:15:54'),(29,'security.requests_per_minute','300','integer','security','حد الطلبات في الدقيقة لكل حساب مسجّل الدخول؛ ما يتجاوزها يُرد 429','Requests per minute per authenticated account; extras answer 429','300',1,0,NULL,NULL,'2026-09-25 21:15:55','2026-09-25 21:15:55'),(30,'security.guest_requests_per_minute','60','integer','security','حد الطلبات في الدقيقة لكل عنوان غير مسجّل','Requests per minute per unauthenticated address','60',1,0,NULL,NULL,'2026-09-25 21:15:55','2026-09-25 21:15:55'),(31,'security.organization_requests_per_minute','1500','integer','security','سقف مشترك لكل حسابات المنشأة الواحدة في الدقيقة','Shared per-minute ceiling for every account of one organization','1500',1,0,NULL,NULL,'2026-09-25 21:15:55','2026-09-25 21:15:55'),(32,'uploads.quota_bytes_per_organization','268435456','integer','uploads','سقف مساحة صور المنتجات ووثائق المنشأة الواحدة بالبايت؛ صفر يعني بلا سقف','Total bytes one organization may hold in product images and filed documents; 0 means unlimited','268435456',1,0,NULL,NULL,'2026-09-25 21:15:55','2026-09-25 21:15:55'),(33,'matching.geo_radius_km','100','integer','matching','نصف قطر المطابقة الجغرافي','Matching radius in km','100',1,0,NULL,NULL,'2026-09-25 21:15:55','2026-09-25 21:15:55'),(34,'geo.max_radius_km','500','integer','matching','أقصى نصف قطر مسموح للبحث القريب','Maximum nearby radius','500',1,1,NULL,NULL,'2026-09-25 21:15:55','2026-09-25 21:15:55');
